//
// HSP_ADDR_MAP
// Creg
// Active Lock control register. There are specific conditions that need to be 
// satisfied in order to write to this register  Write to chkpt_ctrl_active 
// needs special attention. The following two cases cause write to be dropped 
// with AXI SLVERR returned. 1. when CHKPT_CTRL_A[0] = 1, processor writes to 
// chkpt_ctrl_active in user mode, but chkpt_fen_rdata[10] is low 2. when 
// CHKPT_CTRL_A[0] = 1, processor writes to chkpt_ctrl_active in privilege 
// mode, but chkpt_fen_rdata[9] is low. Reset:HSP Reset
//
