// Creg
// I2C Rx/Tx Data Buffer and Command Register; this is the register the CPU 
// writes to when filling the TX FIFO and the CPU reads from when retrieving 
// bytes from RX FIFO.  The size of the register changes as follows:  Write:  
// - 11 bits when IC_EMPTYFIFO_HOLD_MASTER_EN=1  - 9 bits when 
// IC_EMPTYFIFO_HOLD_MASTER_EN=0 Read:  - 12 bits when 
// IC_FIRST_DATA_BYTE_STATUS = 1  - 8 bits when IC_FIRST_DATA_BYTE_STATUS = 0 
// Note: In order for the DW_apb_i2c to continue acknowledging reads, a read 
// command should be written for every byte that is to be received; otherwise 
// the DW_apb_i2c will stop acknowledging.
