// programmed with a value equal to or greater than 2.   Writes to this 
// register succeed only when IC_ENABLE[0] = 0.  Note: The length of setup 
// time is calculated using [(IC_SDA_SETUP - 1) * (ic_clk_period)], so if the 
// user requires 10 ic_clk periods of setup time, they should program a value 
