//
// HSP_ADDR_MAP
// Creg
// I2C Target Address Register  If the configuration parameter 
// I2C_DYNAMIC_TAR_UPDATE is set to 'No' (0), this register is 12 bits wide, 
// and bits 31:12 are reserved. This register can be written to only when 
// IC_ENABLE[0] is set to 0.  However, if I2C_DYNAMIC_TAR_UPDATE = 1, then the 
// register becomes 13 bits wide. In this case, writes to IC_TAR succeed when 
// one of the following conditions are true:  - DW_apb_i2c is NOT enabled 
// (IC_ENABLE[0] is set to 0); or  - DW_apb_i2c is enabled (IC_ENABLE[0]=1); 
// AND DW_apb_i2c is NOT engaged in any Master (tx, rx) operation 
// (IC_STATUS[5]=0); AND DW_apb_i2c is enabled to operate in Master mode 
// (IC_CON[0]=1); AND there are NO entries in the TX FIFO (IC_STATUS[2]=1) You 
// can change the TAR address dynamically without losing the bus, only if the 
// following conditions are met.  - DW_apb_i2c is enabled (IC_ENABLE[0]=1); 
// AND IC_EMPTYFIFO_HOLD_MASTER_EN configuration parameter is set to 1; AND 
// DW_apb_i2c is enabled to operate in Master mode (IC_CON[0]=1); AND there 
// are NO entries in the Tx FIFO and the master is in HOLD state 
// (IC_INTR_STAT[13]=1).  Note: If the software or application is aware that 
// the DW_apb_i2c is not using the TAR address for the pending commands in the 
//     Tx FIFO, then it is possible to update the TAR address even while the 
// Tx FIFO has entries (IC_STATUS[2]= 0).   - It is not necessary to perform 
// any write to this register if DW_apb_i2c is enabled as an I2C slave only. 
//
