// register in the DW_apb_ssi occupies thirty-six 32-bit address locations of 
// the memory map to facilitate AHB burst transfers. Writing to any of these 
// address locations has the same effect as pushing the data from the pwdata 
// bus into the transmit FIFO. Reading from any of these locations has the 
