// The DW_apb_ssi data register is a 16/32-bit (depending on 
// SSI_MAX_XFER_SIZE) read/write buffer for the transmit/receive FIFOs. If the 
// configuration parameter SSI_MAX_XFER_SIZE is set to 32, then all 32 bits 
// are valid, otherwise, only 16 bits ([15:0]) of the register are valid. When 
// the register is read, data in the receive FIFO buffer is accessed. When it 
// is written to, data are moved into the transmit FIFO buffer; a write can 
// occur only when SSI_EN = 1. FIFOs are reset when SSI_EN = 0. NOTE: The DR 
// register in the DW_apb_ssi occupies thirty-six 32-bit address locations of 
// the memory map to facilitate AHB burst transfers. Writing to any of these 
// address locations has the same effect as pushing the data from the pwdata 
// bus into the transmit FIFO. Reading from any of these locations has the 
// same effect as popping data from the receive FIFO onto the prdata bus. The 
// FIFO buffers on the DW_apb_ssi are not addressable. Reset Value: 0x0
//
typedef union _CREG_SPI_DR5
{
    struct
    {
        volatile uint32_t Dr  : 32; // [0:31]
    };

    volatile uint32_t u;

} CREG_SPI_DR5, *PCREG_SPI_DR5;
typedef volatile CREG_SPI_DR5* PVCREG_SPI_DR5;

